import{_ as a,o as t,c as s,a5 as i}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"Reading Evidence Card: From Finished Summary to Real Delivery","description":"Preserve reading task, version, first pass, barrier map, claims and evidence, technical facts, source comparison, independent output, and delayed transfer instead of treating pages or summaries as comprehension.","frontmatter":{"title":"Reading Evidence Card: From Finished Summary to Real Delivery","description":"Preserve reading task, version, first pass, barrier map, claims and evidence, technical facts, source comparison, independent output, and delayed transfer instead of treating pages or summaries as comprehension.","updated":"2026-09-02T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/reading-evidence.en.md","name":"reading-evidence.en.md"}},"headers":[],"relativePath":"en/templates/reading-evidence.md","filePath":"en/templates/reading-evidence.md","lastUpdated":1788307200000}'),n={name:"en/templates/reading-evidence.md"};function d(r,e,l,o,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="reading-evidence-card-from-finished-summary-to-real-delivery" tabindex="-1">Reading Evidence Card: From Finished Summary to Real Delivery <a class="header-anchor" href="#reading-evidence-card-from-finished-summary-to-real-delivery" aria-label="Permalink to &quot;Reading Evidence Card: From Finished Summary to Real Delivery&quot;">​</a></h1><p>Finishing a text is an action, not proof of comprehension. Copy this card into a private note for one article, chapter, documentation section, or source set at a time. Do not record passwords, client data, unauthorised third-party information, or unnecessary personal details.</p><h2 id="_1-define-the-task-reader-and-boundary" tabindex="-1">1. Define the Task, Reader, and Boundary <a class="header-anchor" href="#_1-define-the-task-reader-and-boundary" aria-label="Permalink to &quot;1. Define the Task, Reader, and Boundary&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Reading Evidence - YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real situation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Task: locate information / follow an argument / read documentation / build stamina / synthesise sources / support a decision</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Who must know, decide, execute, or continue something after the reading?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Completion standard:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Time limit:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dictionary / translation / search / notes / AI allowed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Copyright, privacy, and retention boundary:</span></span></code></pre></div><p>Write completion as a result, such as &quot;can run the minimum example under the current version&quot;, not only &quot;finished&quot;.</p><h2 id="_2-record-source-and-version" tabindex="-1">2. Record Source and Version <a class="header-anchor" href="#_2-record-source-and-version" aria-label="Permalink to &quot;2. Record Source and Version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Main source</th><th>Parallel source</th><th>Comparable?</th></tr></thead><tbody><tr><td>Author/maintainer, title, link</td><td></td><td></td><td></td></tr><tr><td>Edition, publication date, or version</td><td></td><td></td><td></td></tr><tr><td>Access date and length</td><td></td><td></td><td></td></tr><tr><td>Author/institution position or interest</td><td></td><td></td><td></td></tr><tr><td>Quotation, image, code, and copyright boundary</td><td></td><td></td><td></td></tr><tr><td>Topic, genre, and difficulty</td><td></td><td></td><td></td></tr></tbody></table><p>Web pages change, become paid, or disappear. Keep necessary citation details; do not copy an entire article without permission.</p><h2 id="_3-preserve-an-unpolished-first-pass" tabindex="-1">3. Preserve an Unpolished First Pass <a class="header-anchor" href="#_3-preserve-an-unpolished-first-pass" aria-label="Permalink to &quot;3. Preserve an Unpolished First Pass&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First-pass conditions:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First-pass time:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Did I look up every word?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One-sentence gist:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">How the text moves:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Three certain details:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What the author/maintainer wants me to believe or do:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One unresolved point:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Action I would take from this understanding:</span></span></code></pre></div><p>Finish the first pass before checking words or explanations. Do not replace it with a polished translation.</p><h2 id="_4-build-a-six-layer-barrier-map" tabindex="-1">4. Build a Six-Layer Barrier Map <a class="header-anchor" href="#_4-build-a-six-layer-barrier-map" aria-label="Permalink to &quot;4. Build a Six-Layer Barrier Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Paragraph/page</th><th>Where I got stuck</th><th>Barrier layer</th><th>Task impact</th><th>This cycle&#39;s action</th></tr></thead><tbody><tr><td></td><td></td><td>vocabulary/grammar / structure/reference / background/schema / argument/evidence / layout/technical / attention/capacity</td><td>meaning-changing / task-blocking / recurring / effortful / low-impact</td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One to three barriers that most affect the task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Low-impact words or sentences I will skip for now:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Possible device, version, fatigue, or environment effects:</span></span></code></pre></div><p>If almost every sentence blocks the gist, choose easier parallel material or learn domain chunks first. Lowering the entry point does not lower the destination.</p><h2 id="_5-map-claims-evidence-and-limits" tabindex="-1">5. Map Claims, Evidence, and Limits <a class="header-anchor" href="#_5-map-claims-evidence-and-limits" aria-label="Permalink to &quot;5. Map Claims, Evidence, and Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Paragraph/page</th><th>Function</th><th>Author claim</th><th>Source evidence/example</th><th>Limit, counterexample, or unknown</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Facts stated directly:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Inference supported by the source:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">My own judgment or association:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Evidence still missing:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What new evidence would change my judgment:</span></span></code></pre></div><p>Separate what the author says from whether you agree. For technical, health, legal, or financial claims, return to reliable primary sources or qualified professional advice.</p><h2 id="_6-technical-documentation-fact-card" tabindex="-1">6. Technical Documentation Fact Card <a class="header-anchor" href="#_6-technical-documentation-fact-card" aria-label="Permalink to &quot;6. Technical Documentation Fact Card&quot;">​</a></h2><p>For an API, SDK, migration guide, command-line help, error reference, or README, add:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Goal and applicable version:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Prerequisites, permissions, and environment:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Minimum input:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Expected output:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Actual output:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Defaults, ranges, order, or side effects:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Failure condition/error:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Limit explicitly stated in the source:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Part I am still inferring:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next test:</span></span></code></pre></div><p>Reading documentation without running, reasoning through, reproducing, or confirming one minimum fact shows that you saw the page. It does not show mastery.</p><h2 id="_7-record-unknown-words-word-families-and-translation" tabindex="-1">7. Record Unknown Words, Word Families, and Translation <a class="header-anchor" href="#_7-record-unknown-words-word-families-and-translation" aria-label="Permalink to &quot;7. Record Unknown Words, Word Families, and Translation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Word/expression</th><th>Role in the task</th><th>Definition/family/collocation checked</th><th>Source location</th><th>Explainable after tools close?</th></tr></thead><tbody><tr><td></td><td>core / recurring / technical / low-impact</td><td></td><td></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Background the translation helped me supply:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">English structure, stance, or qualifier the translation may hide:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Word I decided not to check yet:</span></span></code></pre></div><p>Unknown-word count diagnoses source fit; it does not directly set a level. Word families help guessing and coverage, but a derived form is not automatically usable.</p><h2 id="_8-compare-sources-and-deliver-an-output" tabindex="-1">8. Compare Sources and Deliver an Output <a class="header-anchor" href="#_8-compare-sources-and-deliver-an-output" aria-label="Permalink to &quot;8. Compare Sources and Deliver an Output&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Shared question:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Definition, date, and evidence in source A:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Definition, date, and evidence in source B:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Omitted evidence or institutional interest:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Which differences are factual, and which are values?</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Output</th><th>Audience</th><th>What I delivered</th><th>Audience response</th><th>Traceable basis?</th></tr></thead><tbody><tr><td>Confirmation / minimum test / explanation / decision memo / handover</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>After reading, let a reader, code, decision, or next task test the understanding.</p><h2 id="_9-record-tools-and-feedback" tabindex="-1">9. Record Tools and Feedback <a class="header-anchor" href="#_9-record-tools-and-feedback" aria-label="Permalink to &quot;9. Record Tools and Feedback&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Tool / reviewer / version and date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Did it see the source, my first pass, or my summary?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Source locations it says I missed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Did it confuse fact, inference, and style?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Teacher/peer/primary-source check:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I accepted/rejected, and why:</span></span></code></pre></div><p>AI may extract candidate terms, ask structural questions, and create parallel tasks, but it may invent summaries, citations, background, and author intention. Preserve the first pass before asking it to locate evidence.</p><h2 id="_10-test-delayed-retention-and-transfer" tabindex="-1">10. Test Delayed Retention and Transfer <a class="header-anchor" href="#_10-test-delayed-retention-and-transfer" aria-label="Permalink to &quot;10. Test Delayed Retention and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>What is removed</th><th>Changed condition</th><th>Output</th><th>Result</th></tr></thead><tbody><tr><td>Day 1</td><td>No full translation or AI summary</td><td>Main source</td><td>First pass and five-sentence reconstruction</td><td></td></tr><tr><td>Days 3-7</td><td>Old notes and dictionary removed</td><td>Parallel source</td><td>Gist, evidence, and inference</td><td></td></tr><tr><td>Day 14</td><td>Recent feedback removed</td><td>New topic or genre</td><td>Explanation, test, or decision memo</td><td></td></tr><tr><td>Day 30</td><td>All prompts closed</td><td>Real document, report, or handover</td><td>Complete delivery</td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Method still available after seven days:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Barrier that returned after the source changed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Did word-by-word translation or summary dependence decrease?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Which post-reading action remains unstable?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One variable for the next cycle:</span></span></code></pre></div><h2 id="_11-score-and-decide" tabindex="-1">11. Score and Decide <a class="header-anchor" href="#_11-score-and-decide" aria-label="Permalink to &quot;11. Score and Decide&quot;">​</a></h2><p>Score 0-2: <code>0=not completed</code>, <code>1=prompt-dependent or unstable</code>, <code>2=completed under the current condition</code>.</p><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Day 1</th><th style="text-align:right;">Day 7</th><th style="text-align:right;">Day 14</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Preserve the first-pass main line</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Separate claim, evidence, and inference</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Locate the barrier layer and choose an action</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Verify a technical fact or source location</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Reconstruct after tools close</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Deliver after source, topic, or genre changes</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current evidence supports: continue main source / downgrade to extensive reading / replace source / move to another problem</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Most important evidence:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Conclusion I still cannot draw:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review date:</span></span></code></pre></div><p>Related chapters: <a href="./../threads/part-1/4-reading">Reading: From Word-by-word Translation to Claims and Evidence</a> | <a href="./../threads/part-1/2-vocabulary">Vocabulary</a> | <a href="./../threads/part-1/grammar">Grammar</a> | <a href="./../threads/part-1/3-listening">Listening</a> | <a href="./../threads/part-1/7-ai">Learning English with AI</a> | <a href="./evidence-chain">Evidence Chain Template</a></p>`,42)])])}const u=a(n,[["render",d]]);export{k as __pageData,u as default};
